const approvedItems = $('Read Approved Outreach').all();
const outreachItems = $('Read Outreach Log').all();

const approvedRows = approvedItems.map((item) => (item && item.json) || {});
const outreachRows = outreachItems.map((item) => (item && item.json) || {});

const normalize = (value) => (value === undefined || value === null ? '' : String(value).trim());

const STATUS_PRE_SEND = new Set(['', 'not_ready', 'queued', 'prepared']);
const STATUS_POST_SEND = new Set(['contacted', 'follow_up_due', 'replied', 'qualified', 'demo', 'pilot', 'won', 'lost']);
const STATUS_SUPPRESSED = new Set(['suppressed']);
const KNOWN_STATUS_SET = new Set(['', 'not_ready', 'queued', 'prepared', 'contacted', 'follow_up_due', 'replied', 'qualified', 'demo', 'pilot', 'won', 'lost', 'suppressed']);

const round4 = (x) => Math.round(x * 10000) / 10000;

const sortByLeadId = (a, b) => (a.lead_id < b.lead_id ? -1 : a.lead_id > b.lead_id ? 1 : 0);

const latestRecord = (records) => {
  let latest = null;
  for (const record of records) {
    if (!latest) { latest = record; continue; }
    if (record.sentAt > latest.sentAt || (record.sentAt === latest.sentAt && record.index > latest.index)) latest = record;
  }
  return latest;
};

const firstRecord = (records) => {
  let first = null;
  for (const record of records) {
    if (!first) { first = record; continue; }
    if (record.sentAt < first.sentAt || (record.sentAt === first.sentAt && record.index < first.index)) first = record;
  }
  return first;
};

const buildApprovedIndex = (rows) => {
  const index = new Map();
  const malformed = [];
  const duplicates = [];
  rows.forEach((row, i) => {
    const leadId = normalize(row.lead_id);
    const approvedAt = normalize(row.approved_at);
    if (!leadId || !approvedAt) {
      malformed.push({ lead_id: leadId, business_name: normalize(row.business_name), status: normalize(row.status), approved_at: approvedAt, reason: leadId ? 'missing approved_at' : 'missing lead_id', index: i, row });
      return;
    }
    if (index.has(leadId)) {
      duplicates.push({ lead_id: leadId, business_name: normalize(row.business_name), approved_at: approvedAt, index: i, row });
      return;
    }
    index.set(leadId, { lead_id: leadId, business_name: normalize(row.business_name), niche: normalize(row.niche), status: normalize(row.status), approved_at: approvedAt, index: i, row });
  });
  return { index, malformed, duplicates };
};

const buildOutreachIndex = (rows) => {
  const byLead = new Map();
  const malformed = [];
  rows.forEach((row, i) => {
    const leadId = normalize(row.lead_id);
    const sentAt = normalize(row.sent_at);
    if (!leadId || !sentAt) {
      malformed.push({ outreach_id: normalize(row.outreach_id), lead_id: leadId, business_name: normalize(row.business_name), sent_at: sentAt, reason: leadId ? 'missing sent_at' : 'missing lead_id', index: i, row });
      return;
    }
    if (!byLead.has(leadId)) byLead.set(leadId, []);
    byLead.get(leadId).push({ index: i, sentAt, row });
  });
  const index = new Map();
  for (const [leadId, records] of byLead) {
    const first = firstRecord(records);
    const latest = latestRecord(records);
    const latestRow = latest.row;
    const channels = [...new Set(records.map((r) => normalize(r.row.channel)).filter(Boolean))].sort();
    index.set(leadId, { lead_id: leadId, business_name: normalize(latestRow.business_name), count: records.length, first_sent_at: first.sentAt, latest_sent_at: latest.sentAt, channels, latest_reply_status: normalize(latestRow.reply_status), latest_outcome: normalize(latestRow.outcome), latest_call_booked: normalize(latestRow.call_booked), latest_paid_pilot_interest: normalize(latestRow.paid_pilot_interest), references: records });
  }
  return { index, malformed };
};

const classifyApprovals = (approvedIndex, outreachIndex) => {
  const results = [];
  for (const entry of approvedIndex.values()) {
    const oEntry = outreachIndex.get(entry.lead_id);
    const outreachCount = oEntry ? oEntry.count : 0;
    let category;
    if (outreachCount === 0) category = 'APPROVED_NO_OUTREACH';
    else if (outreachCount === 1) category = 'APPROVED_WITH_OUTREACH';
    else category = 'MULTIPLE_OUTREACH';
    results.push({ lead_id: entry.lead_id, business_name: entry.business_name, category, outreach_count: outreachCount, first_sent_at: oEntry ? oEntry.first_sent_at : '', latest_sent_at: oEntry ? oEntry.latest_sent_at : '', channels: oEntry ? oEntry.channels : [], status: entry.status });
  }
  results.sort(sortByLeadId);
  return results;
};

const findStatusMismatches = (approvedIndex, outreachIndex) => {
  const mismatches = [];
  for (const entry of approvedIndex.values()) {
    const oEntry = outreachIndex.get(entry.lead_id);
    const outreachCount = oEntry ? oEntry.count : 0;
    const hasActivity = outreachCount > 0;
    const status = entry.status;
    let reason = '';
    if (STATUS_POST_SEND.has(status) && !hasActivity) reason = `status "${status}" implies outreach activity but none is logged in Outreach Log`;
    else if (hasActivity && STATUS_PRE_SEND.has(status)) reason = `outreach activity is logged in Outreach Log while status remains "${status}"`;
    if (!reason) continue;
    mismatches.push({ lead_id: entry.lead_id, business_name: entry.business_name, status, outreach_count: outreachCount, first_sent_at: oEntry ? oEntry.first_sent_at : '', latest_sent_at: oEntry ? oEntry.latest_sent_at : '', reason });
  }
  mismatches.sort(sortByLeadId);
  return mismatches;
};

const findOrphans = (outreachIndex, approvedIndex) => {
  const orphans = [];
  for (const [leadId, oEntry] of outreachIndex) {
    if (approvedIndex.has(leadId)) continue;
    orphans.push({ lead_id: leadId, business_name: oEntry.business_name, outreach_count: oEntry.count, first_sent_at: oEntry.first_sent_at, latest_sent_at: oEntry.latest_sent_at });
  }
  orphans.sort(sortByLeadId);
  return orphans;
};

const countNonCanonicalStatuses = (approvedIndex) => {
  let n = 0;
  for (const entry of approvedIndex.values()) {
    if (!KNOWN_STATUS_SET.has(entry.status)) n += 1;
  }
  return n;
};

const sortExceptions = (a, b) => {
  const ka = [a.exception_type, a.lead_id || '', a.details || ''];
  const kb = [b.exception_type, b.lead_id || '', b.details || ''];
  for (let i = 0; i < ka.length; i += 1) {
    if (ka[i] < kb[i]) return -1;
    if (ka[i] > kb[i]) return 1;
  }
  return 0;
};

const detectedAt = new Date().toISOString();
const runAt = detectedAt;
const runId = 'RECONCILIATION-' + detectedAt.replace(/[^\d]/g, '').slice(0, 14);

let approvedError = '';
let outreachError = '';
if (approvedItems.length === 1 && approvedItems[0].json && approvedItems[0].json._source_read_error) approvedError = approvedItems[0].json._source_read_error;
if (outreachItems.length === 1 && outreachItems[0].json && outreachItems[0].json._source_read_error) outreachError = outreachItems[0].json._source_read_error;

if (approvedError || outreachError) {
  const nullFields = { approved_total: null, approved_with_outreach: null, approved_no_outreach: null, approval_duplicates: null, coverage_rate: null, outreach_total: null, unique_leads_with_outreach: null, multiple_outreach_leads: null, orphan_outreach: null, malformed_approvals: null, malformed_outreach: null, status_mismatches: null, non_canonical_statuses: null, healthy_records: null, exception_count: null };
  return [
    { json: Object.assign({ run_id: runId, status: 'RECONCILIATION_INCOMPLETE', run_at: runAt, detected_at: detectedAt }, nullFields, { approvals: [], exceptions: [], sources: { approved_ok: !approvedError, outreach_ok: !outreachError, approved_read_error: approvedError, outreach_read_error: outreachError } }) },
    { json: { run_id: runId, exception_count: null, exceptions: [] } },
  ];
}
const approved = buildApprovedIndex(approvedRows);
const outreach = buildOutreachIndex(outreachRows);

const approvals = classifyApprovals(approved.index, outreach.index);
const mismatches = findStatusMismatches(approved.index, outreach.index);
const orphans = findOrphans(outreach.index, approved.index);
const nonCanonicalStatuses = countNonCanonicalStatuses(approved.index);

const exceptionRows = [];
for (const m of mismatches) exceptionRows.push({ run_id: runId, lead_id: m.lead_id, business_name: m.business_name, exception_type: 'STATUS_MISMATCH', severity: 'WARNING', approved_status: m.status, outreach_count: m.outreach_count, first_sent_at: m.first_sent_at, latest_sent_at: m.latest_sent_at, outreach_id: '', details: m.reason, detected_at: detectedAt });
for (const o of orphans) exceptionRows.push({ run_id: runId, lead_id: o.lead_id, business_name: o.business_name, exception_type: 'OUTREACH_WITHOUT_APPROVAL', severity: 'ERROR', approved_status: '', outreach_count: o.outreach_count, first_sent_at: o.first_sent_at, latest_sent_at: o.latest_sent_at, outreach_id: '', details: 'Outreach Log has records but no matching Approved Outreach row', detected_at: detectedAt });
for (const m of outreach.malformed) exceptionRows.push({ run_id: runId, lead_id: m.lead_id, business_name: m.business_name, exception_type: 'MALFORMED_OUTREACH', severity: 'ERROR', approved_status: '', outreach_count: 1, first_sent_at: '', latest_sent_at: '', outreach_id: m.outreach_id || '', details: m.reason, detected_at: detectedAt });
for (const m of approved.malformed) exceptionRows.push({ run_id: runId, lead_id: m.lead_id, business_name: m.business_name, exception_type: 'MALFORMED_APPROVAL', severity: 'ERROR', approved_status: m.status || '', outreach_count: 0, first_sent_at: '', latest_sent_at: '', outreach_id: '', details: m.reason, detected_at: detectedAt });
exceptionRows.sort(sortExceptions);

const approvedWith = approvals.filter((a) => a.category !== 'APPROVED_NO_OUTREACH').length;
const approvedWithout = approvals.filter((a) => a.category === 'APPROVED_NO_OUTREACH').length;
const classifiable = approvedWith + approvedWithout;
const mismatchLeadIds = new Set(mismatches.map((m) => m.lead_id));
const healthy = approvals.filter((a) => a.outreach_count > 0 && !mismatchLeadIds.has(a.lead_id)).length;

const report = {
  run_id: runId,
  status: 'COMPLETED',
  run_at: runAt,
  detected_at: detectedAt,
  approved_total: approvedRows.length,
  approved_with_outreach: approvedWith,
  approved_no_outreach: approvedWithout,
  approval_duplicates: approved.duplicates.length,
  coverage_rate: classifiable > 0 ? round4(approvedWith / classifiable) : null,
  outreach_total: outreachRows.length,
  unique_leads_with_outreach: outreach.index.size,
  multiple_outreach_leads: approvals.filter((a) => a.outreach_count > 1).length,
  orphan_outreach: orphans.length,
  malformed_approvals: approved.malformed.length,
  malformed_outreach: outreach.malformed.length,
  status_mismatches: mismatches.length,
  non_canonical_statuses: nonCanonicalStatuses,
  healthy_records: healthy,
  exception_count: exceptionRows.length,
  approvals,
  exceptions: exceptionRows,
  sources: { approved_ok: true, outreach_ok: true, approved_read_error: '', outreach_read_error: '' },
};

return [
  { json: report },
  { json: { run_id: report.run_id, exception_count: report.exception_count, exceptions: report.exceptions } },
];
